// Evidence-backed request-path tests for the Misc leaf (Phase 3.1).
//
// Generated by scripts/research/gen-31-tests.py from the rows in api.md, which in turn come from
// docs/research/apk-endpoints.md. Each test calls the method and inspects the URL that actually
// reaches `fetch`, so a rename or a route regression fails here rather than in production.

import BandlabSDK from 'bandlabx';

function makeClient(): BandlabSDK {
  return new BandlabSDK({ bearerToken: 'My Bearer Token', baseURL: 'http://127.0.0.1:4010' });
}

/** Run `fn`, capture the URL of the first request, and answer it with a stub response. */
async function captureURL(fn: (c: BandlabSDK) => Promise<unknown>): Promise<string> {
  const calls: string[] = [];
  const realFetch = globalThis.fetch;
  globalThis.fetch = (async (input: any) => {
    calls.push(typeof input === 'string' ? input : input?.url ?? String(input));
    return new Response('{}', { status: 200, headers: { 'content-type': 'application/json' } });
  }) as typeof fetch;
  try {
    await fn(makeClient()).catch(() => undefined);
  } finally {
    globalThis.fetch = realFetch;
  }
  if (!calls.length) throw new Error('no request was issued');
  return calls[0]!;
}

describe('Misc paths match the APK evidence', () => {
  test('POST /chat/authorizations hits /chat/authorizations', async () => {
    const url = await captureURL((c) => c.misc.createChatAuthorization({}));
    expect(url).toContain('/chat/authorizations');
  });

  test('GET /experiment/beats-filters hits /experiment/beats-filters', async () => {
    const url = await captureURL((c) => c.misc.retrieveBeatsFilters());
    expect(url).toContain('/experiment/beats-filters');
  });

  test('GET /options hits /options', async () => {
    const url = await captureURL((c) => c.misc.retrieveOptions());
    expect(url).toContain('/options');
  });

  test('GET /social-links hits /social-links', async () => {
    const url = await captureURL((c) => c.misc.listSocialLinks({}));
    expect(url).toContain('/social-links');
  });

  test('POST /tracking/v2/collect hits /tracking/v2/collect', async () => {
    const url = await captureURL((c) => c.misc.collectTracking({}));
    expect(url).toContain('/tracking/v2/collect');
  });
});
